import React from "react";

export default function PostCard({ post }) {
  return (
    <div className="card">

      <div className="card-header">
        <img src="https://i.pravatar.cc/50" alt="" />
        <h4>{post.user}</h4>
      </div>

      <img src={post.imagen} alt="" />

      <p>{post.descripcion}</p>

      <audio controls src={post.cancion}></audio>

    </div>
  );
}
